//! Push notifications: ntfy (phone/desktop apps, self-hostable) and macOS notifications while the window is hidden.
//! Notifies when a task finishes and when an agent waits for a permission. The ntfy topic is generated by Nexus,
//! stored in Keychain and sent only inside curl's stdin config.
use super::remote_channels as rc;
use serde_json::{json, Value};
use std::process::Stdio;
use tauri::{Listener, Manager};
use tokio::{io::AsyncWriteExt, process::Command};

fn quoted(v: &str) -> String {
    format!(
        "\"{}\"",
        v.replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
            .replace('\r', "\\r")
    )
}
pub fn payload(topic: &str, title: &str, message: &str, priority: &str) -> Value {
    json!({"topic":topic,"title":title.chars().take(120).collect::<String>(),"message":message.chars().take(1500).collect::<String>(),"priority":match priority{"high"=>4,"low"=>2,_=>3},"tags":[if priority=="high"{"lock"}else{"robot"}]})
}
pub async fn send(
    cfg: &rc::Config,
    topic: &str,
    title: &str,
    message: &str,
    priority: &str,
) -> Result<(), String> {
    let server = if cfg.push_server.trim().is_empty() {
        "https://ntfy.sh"
    } else {
        cfg.push_server.trim().trim_end_matches('/')
    };
    if !server.starts_with("https://") {
        return Err("Сервер уведомлений должен использовать HTTPS".into());
    }
    let conf = format!(
        "url = {}\nrequest = \"POST\"\nheader = \"Content-Type: application/json\"\ndata-binary = {}\n",
        quoted(server),
        quoted(&payload(topic, title, message, priority).to_string())
    );
    let mut child = crate::new_command(super::curl_path())
        .args([
            "--silent",
            "--show-error",
            "--max-time",
            "20",
            "--proto",
            "=https",
            "--fail",
            "--config",
            "-",
        ])
        .kill_on_drop(true)
        .stdin(Stdio::piped())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|_| "Не удалось запустить curl")?;
    child
        .stdin
        .take()
        .ok_or("Нет входного канала")?
        .write_all(conf.as_bytes())
        .await
        .map_err(|_| "Ошибка отправки")?;
    let out = child.wait_with_output().await.map_err(|_| "Ошибка сети")?;
    if out.status.success() {
        Ok(())
    } else {
        Err(format!(
            "Уведомление не отправлено: {}",
            String::from_utf8_lossy(&out.stderr)
                .trim()
                .chars()
                .take(200)
                .collect::<String>()
        ))
    }
}
fn mac_notify(title: &str, message: &str) {
    // Values travel as argv items of the script, never spliced into AppleScript source.
    let clean = |s: &str| {
        let s: String = s.chars().filter(|c| !c.is_control()).take(240).collect();
        if s.starts_with('-') {
            format!("· {s}")
        } else {
            s
        }
    };
    let _ = std::process::Command::new("/usr/bin/osascript")
        .args([
            "-e",
            "on run argv",
            "-e",
            "display notification (item 2 of argv) with title (item 1 of argv)",
            "-e",
            "end run",
            &clean(title),
            &clean(message),
        ])
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .spawn();
}
fn window_hidden(app: &tauri::AppHandle) -> bool {
    app.get_webview_window("main")
        .map(|w| !w.is_visible().unwrap_or(true) || w.is_minimized().unwrap_or(false))
        .unwrap_or(true)
}
fn config() -> Option<rc::Config> {
    rc::load_configs()
        .ok()?
        .into_iter()
        .find(|c| c.kind == "push" && c.enabled)
}
fn in_scope(cfg: &rc::Config, chat: &str) -> bool {
    cfg.push_scope == "all" || rc::is_remote_chat(chat)
}
async fn deliver(
    app: tauri::AppHandle,
    cfg: rc::Config,
    title: String,
    message: String,
    priority: &'static str,
) {
    if cfg.mac_notify && window_hidden(&app) {
        mac_notify(&title, &message)
    }
    match rc::secret("push").ok().filter(|t| !t.is_empty()) {
        Some(topic) => {
            if let Err(e) = send(&cfg, &topic, &title, &message, priority).await {
                rc::push_log(&app, &e)
            }
        }
        None => rc::push_log(&app, "Нет темы уведомлений — сохраните настройки ещё раз"),
    }
}
/// Builds the "task finished" notification from stored chat data.
pub fn finished_text(chat: &str, status: &str) -> Option<(String, String)> {
    let (project, title, task, answer) = rc::chat_summary(chat)?;
    let label = match (status, task.as_str()) {
        ("error", _) => "ошибка",
        (_, "done") => "готово, проверки пройдены",
        (_, "review") => "нужна проверка",
        (_, "stopped") => "остановлено",
        _ => "ответ готов",
    };
    Some((
        format!("{project}: {label}"),
        format!("{title}\n{}", answer.chars().take(300).collect::<String>()),
    ))
}
pub fn start(app: &tauri::AppHandle) {
    let a = app.clone();
    app.listen_any("chat-activity", move |e| {
        let Ok(v) = serde_json::from_str::<Value>(e.payload()) else {
            return;
        };
        let (Some(chat), Some(status)) = (v["chatId"].as_str(), v["status"].as_str()) else {
            return;
        };
        if status == "running" {
            return;
        }
        let Some(cfg) = config() else { return };
        if !in_scope(&cfg, chat) {
            return;
        }
        let (chat, status) = (chat.to_string(), status.to_string());
        let app = a.clone();
        // chat-activity fires just before the task status is stored; give it a moment so the summary is accurate.
        tauri::async_runtime::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(700)).await;
            if let Some((t, m)) = finished_text(&chat, &status) {
                deliver(app, cfg, t, m, "default").await
            }
        });
    });
    let a = app.clone();
    app.listen_any("chat-permission", move |e| {
        let Ok(v) = serde_json::from_str::<Value>(e.payload()) else {
            return;
        };
        let Some(chat) = v["chatId"].as_str() else { return };
        let Some(cfg) = config() else { return };
        if !in_scope(&cfg, chat) {
            return;
        }
        let title = rc::chat_summary(chat)
            .map(|s| s.1)
            .unwrap_or_else(|| "Nexus".into());
        let app = a.clone();
        tauri::async_runtime::spawn(deliver(
            app,
            cfg,
            format!("Агент ждёт разрешения · {}", v["provider"].as_str().unwrap_or("")),
            format!("{title}\nОтветьте в Nexus или в канале задачи (/allow КОД)."),
            "high",
        ));
    });
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn payload_is_bounded_json() {
        let p = payload("nexus-abc", "Т".repeat(500).as_str(), &"x".repeat(5000), "high");
        assert_eq!(p["topic"], "nexus-abc");
        assert_eq!(p["priority"], 4);
        assert_eq!(p["title"].as_str().unwrap().chars().count(), 120);
        assert_eq!(p["message"].as_str().unwrap().len(), 1500);
        assert_eq!(payload("t", "a", "b", "x")["priority"], 3);
        assert_eq!(quoted("a\"\n"), "\"a\\\"\\n\"");
    }
}
